fn fibonacci(n: usize) -> Vec<i32> {
    assert!(n >= 2, "n must be at least 2");

    let mut ret: Vec<i32> = Vec::with_capacity(n);
    ret.push(0);
    ret.push(1);

    for i in 2..n {
        let next = ret[i - 1]
            .checked_add(ret[i - 2])
            .expect("Fibonacci value does not fit in i32");
        ret.push(next);
    }

    ret
}